// Marks when a claimed effect's visible request goes out, unless its run was cancelled
// meanwhile: a lookup's wait for a request in flight counts from here.
func (q *Queries) TouchEffect(ctx context.Context, arg TouchEffectParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, touchEffect,
		arg.ClaimedAt,
		arg.LastRequestAt,
		arg.UpdatedAt,
		arg.EffectID,
		arg.Version,
		arg.ClaimedBy,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const useApproval = `-- name: UseApproval :execrows
UPDATE approvals SET used_at = ? WHERE approval_id = ? AND status = 'APPROVED' AND used_at IS NULL
`

type UseApprovalParams struct {
	UsedAt     sql.NullString
	ApprovalID string
}

func (q *Queries) UseApproval(ctx context.Context, arg UseApprovalParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, useApproval, arg.UsedAt, arg.ApprovalID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
